						end
					end
					else if (!dec[8] || osr_empty) begin
						if (tx_empty) begin
							sm_txunder_ev = 1;
							if (dec[7])
								stall = 1;
							else begin
								we_osr = 1;
								wdata_osr = x;
								we_osr_count = 1;
								wdata_osr_count = 1'sb0;
							end
						end
						else begin
							sm_tx_pop = 1;
							we_osr = 1;
							wdata_osr = tx_pop_data;
							we_osr_count = 1;
							wdata_osr_count = 1'sb0;
						end
					end
