					(* full_case, parallel_case *)
					case (instr[2:0])
						3'b000: src_v = pins_bus(0);
						3'b001: src_v = x;
						3'b010: src_v = y;
						3'b011: src_v = 1'sb0;
						3'b101: src_v = status_val;
						3'b110: src_v = isr;
						3'b111: src_v = osr;
