							out_data = val;
						end
						3'b001: begin
							we_x = 1;
							wdata_x = val;
						end
						3'b010: begin
							we_y = 1;
							wdata_y = val;
						end
						3'b100: begin
							request_exec = 1;
							request_exec_instr = sv2v_cast_E0268(val[15:0]);
