						sv2v_cast_FA7F8(3'b001): begin
							we_x = 1;
							wdata_x = sv2v_cast_6778B(dec[6-:5]);
						end
						sv2v_cast_FA7F8(3'b010): begin
							we_y = 1;
							wdata_y = sv2v_cast_6778B(dec[6-:5]);
						end
						sv2v_cast_FA7F8(3'b100): do_set_pindirs = 1;
						default:
							;
					endcase
				default:
					;
			endcase
