	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			pc <= 1'sb0;
			delay_rem <= 1'sb0;
			next_pc_r <= 1'sb0;
			isr_count <= 1'sb0;
			osr_count <= 6'd32;
			pending_exec <= 0;
			exec_instr <= 1'sb0;
			host_pending <= 0;
			host_instr <= 1'sb0;
			irq_hold <= 0;
			irq_hold_idx <= 1'sb0;
		end
		else if (sm_restart) begin
			pc <= 1'sb0;
			delay_rem <= 1'sb0;
			next_pc_r <= 1'sb0;
			isr_count <= 1'sb0;
			osr_count <= 6'd32;
			pending_exec <= 0;
			exec_instr <= 1'sb0;
			host_pending <= 0;
			host_instr <= 1'sb0;
			irq_hold <= 0;
			irq_hold_idx <= 1'sb0;
		end
		else begin
			if (host_exec_stb) begin
				host_pending <= 1'b1;
				host_instr <= host_exec_instr;
			end
			if (active) begin
				if (delaying) begin
					delay_rem <= delay_rem - 5'd1;
					if (delay_rem == 5'd1)
						pc <= next_pc_r;
				end
				else if (do_exec) begin
					if (((!irq_hold && (dec[17-:3] == sv2v_cast_04AD1(3'b110))) && dec[7]) && !dec[8]) begin
						irq_hold <= 1;
						irq_hold_idx <= irq_idx_f(dec[6-:5]);
					end
					if (irq_hold && !irq_flags[irq_hold_idx])
						irq_hold <= 0;
					if (!stall) begin
						if (we_isr_count)
							isr_count <= wdata_isr_count;
						if (we_osr_count)
							osr_count <= wdata_osr_count;
						if (host_pending) begin
							if (!host_exec_stb)
								host_pending <= 1'b0;
							pending_exec <= 0;
						end
						else if (request_exec) begin
							pending_exec <= 1;
							exec_instr <= request_exec_instr;
						end
						else
							pending_exec <= 0;
						next_pc_r <= next_pc_c;
						if (!ignore_delay && (instr_delay != {5 {1'sb0}}))
							delay_rem <= instr_delay;
						else
							pc <= next_pc_c;
					end
					else if (irq_hold && !irq_flags[irq_hold_idx]) begin
						irq_hold <= 0;
						pending_exec <= 0;
						next_pc_r <= next_pc_c;
						if (!ignore_delay && (instr_delay != {5 {1'sb0}}))
							delay_rem <= instr_delay;
						else
							pc <= next_pc_c;
					end
				end
			end
			else if (host_force) begin
				if (!stall) begin
					if (we_isr_count)
						isr_count <= wdata_isr_count;
					if (we_osr_count)
						osr_count <= wdata_osr_count;
					if (!host_exec_stb)
						host_pending <= 1'b0;
					pending_exec <= 0;
					pc <= next_pc_c;
				end
			end
		end
	initial _sv2v_0 = 0;
endmodule
