		else begin
			imem_wr_en <= 1'b0;
			tx_push <= 1'sb0;
			rx_pop <= 1'sb0;
			wr_done <= 1'b0;
			rd_done <= 1'b0;
			clkdiv_restart <= 1'sb0;
			sm_restart <= 1'sb0;
			host_exec_stb <= 1'sb0;
			begin : sv2v_autoblock_5
				reg [NUM_SM - 1:0] rxstall_n;
				reg [NUM_SM - 1:0] rxunder_n;
				reg [NUM_SM - 1:0] txover_n;
				reg [NUM_SM - 1:0] txstall_n;
				rxstall_n = fdbg_rxstall_r | fdbg_rxover;
				rxunder_n = fdbg_rxunder_r | fdbg_rxunder;
				txover_n = fdbg_txover_r | fdbg_txover;
				txstall_n = fdbg_txstall_r | fdbg_txunder;
				if ((wr_valid && !wr_done) && (a32(wr_addr) == kraken_pkg_AXIL_ADDR_FDEBUG)) begin
					rxstall_n = rxstall_n & ~wr_data[kraken_pkg_AXIL_FDEBUG_RXSTALL_LSB+:NUM_SM];
					rxunder_n = rxunder_n & ~wr_data[kraken_pkg_AXIL_FDEBUG_RXUNDER_LSB+:NUM_SM];
					txover_n = txover_n & ~wr_data[kraken_pkg_AXIL_FDEBUG_TXOVER_LSB+:NUM_SM];
					txstall_n = txstall_n & ~wr_data[kraken_pkg_AXIL_FDEBUG_TXSTALL_LSB+:NUM_SM];
				end
				if (rd_valid && !rd_done) begin : sv2v_autoblock_6
					reg signed [31:0] s;
					for (s = 0; s < NUM_SM; s = s + 1)
						if ((a32(rd_addr) == (kraken_pkg_AXIL_ADDR_RXF0 + (s << 3))) && rx_empty[s])
							rxunder_n[s] = 1'b1;
				end
				fdbg_rxstall_r <= rxstall_n;
				fdbg_rxunder_r <= rxunder_n;
				fdbg_txover_r <= txover_n;
				fdbg_txstall_r <= txstall_n;
			end
			if (wr_valid && !wr_done) begin
				(* full_case, parallel_case *)
				case (a32(wr_addr))
					kraken_pkg_AXIL_ADDR_CTRL: begin : sv2v_autoblock_7
						reg [31:0] v;
						v = merge_wstrb(ctrl_rd, wr_data, wr_strb);
						ctrl_enable <= v[NUM_SM - 1:0];
						irq_ie <= v[kraken_pkg_AXIL_CTRL_IRQ_IE_LSB+:8];
						sm_restart <= v[kraken_pkg_AXIL_CTRL_SM_RESTART_LSB+:NUM_SM];
						clkdiv_restart <= v[kraken_pkg_AXIL_CTRL_CLKDIV_RESTART_LSB+:NUM_SM];
					end
					kraken_pkg_AXIL_ADDR_IRQ: irq_force_sticky <= irq_force_sticky & ~wr_data[7:0];
					kraken_pkg_AXIL_ADDR_IRQ_FORCE: irq_force_sticky <= irq_force_sticky | wr_data[7:0];
					kraken_pkg_AXIL_ADDR_IMEM_ADDR: begin : sv2v_autoblock_8
						reg [31:0] v_imem_addr;
						v_imem_addr = merge_wstrb({27'b000000000000000000000000000, imem_addr_r}, wr_data, wr_strb);
						imem_addr_r <= v_imem_addr[4:0];
					end
					kraken_pkg_AXIL_ADDR_IMEM_DATA: begin : sv2v_autoblock_9
						reg [31:0] v_imem_data;
						v_imem_data = merge_wstrb(32'b00000000000000000000000000000000, wr_data, wr_strb);
						imem_wr_en <= 1'b1;
						imem_wr_addr <= imem_addr_r;
						imem_wr_data <= v_imem_data[15:0];
						imem_addr_r <= imem_addr_r + 5'd1;
					end
					kraken_pkg_AXIL_ADDR_FDEBUG:
						;
					default: begin : sv2v_autoblock_10
						reg signed [31:0] s;
						for (s = 0; s < NUM_SM; s = s + 1)
							begin
								if (a32(wr_addr) == kraken_pkg_axil_addr_clkdiv(s))
									clkdiv_reg[s] <= merge_wstrb(clkdiv_reg[s], wr_data, wr_strb) & 32'hffffff00;
								if (a32(wr_addr) == kraken_pkg_axil_addr_execctrl(s))
									execctrl[s] <= merge_wstrb(execctrl[s], wr_data, wr_strb);
								if (a32(wr_addr) == kraken_pkg_axil_addr_shiftctrl(s))
									shiftctrl[s] <= merge_wstrb(shiftctrl[s], wr_data, wr_strb);
								if (a32(wr_addr) == kraken_pkg_axil_addr_pinctrl(s))
									pinctrl[s] <= merge_wstrb(pinctrl[s], wr_data, wr_strb);
								if (a32(wr_addr) == kraken_pkg_axil_addr_sm_instr(s)) begin : sv2v_autoblock_11
									reg [31:0] v_instr;
									v_instr = merge_wstrb({16'b0000000000000000, sm_instr_hold[s]}, wr_data, wr_strb);
									sm_instr_hold[s] <= v_instr[15:0];
									host_exec_instr[16 * s+:16] <= v_instr[15:0];
									host_exec_stb[s] <= 1'b1;
								end
								if (a32(wr_addr) == (kraken_pkg_AXIL_ADDR_TXF0 + (s << 3))) begin
									tx_hold[s] <= merge_wstrb(tx_hold[s], wr_data, wr_strb);
									tx_push[s] <= 1'b1;
								end
							end
					end
				endcase
				wr_done <= 1'b1;
			end
			if (rd_valid && !rd_done) begin
				(* full_case, parallel_case *)
				case (a32(rd_addr))
					kraken_pkg_AXIL_ADDR_CTRL: rd_data <= ctrl_rd;
					kraken_pkg_AXIL_ADDR_FSTAT: rd_data <= fstat_word;
					kraken_pkg_AXIL_ADDR_IRQ: rd_data <= {24'b000000000000000000000000, irq_visible};
					kraken_pkg_AXIL_ADDR_IRQ_FORCE: rd_data <= {24'b000000000000000000000000, irq_force_sticky};
					kraken_pkg_AXIL_ADDR_IMEM_ADDR: rd_data <= {27'b000000000000000000000000000, imem_addr_r};
					kraken_pkg_AXIL_ADDR_IMEM_DATA: rd_data <= 32'h00000000;
					kraken_pkg_AXIL_ADDR_FDEBUG: rd_data <= fdebug_word;
					kraken_pkg_AXIL_ADDR_FLEVEL: rd_data <= flevel_word;
					kraken_pkg_AXIL_ADDR_ID: rd_data <= kraken_pkg_AXIL_ID_VALUE;
					default: begin
						rd_data <= 32'hdeadbeef;
						begin : sv2v_autoblock_12
							reg signed [31:0] s;
							for (s = 0; s < NUM_SM; s = s + 1)
								begin
									if (a32(rd_addr) == kraken_pkg_axil_addr_clkdiv(s))
										rd_data <= clkdiv_reg[s] & 32'hffffff00;
									if (a32(rd_addr) == kraken_pkg_axil_addr_execctrl(s))
										rd_data <= execctrl[s];
									if (a32(rd_addr) == kraken_pkg_axil_addr_shiftctrl(s))
										rd_data <= shiftctrl[s];
									if (a32(rd_addr) == kraken_pkg_axil_addr_pinctrl(s))
										rd_data <= pinctrl[s];
									if (a32(rd_addr) == kraken_pkg_axil_addr_sm_instr(s))
										rd_data <= {16'b0000000000000000, sm_instr_hold[s]};
									if (a32(rd_addr) == kraken_pkg_axil_addr_sm_addr(s))
										rd_data <= {27'b000000000000000000000000000, sm_pc_bus[5 * s+:5]};
									if (a32(rd_addr) == (kraken_pkg_AXIL_ADDR_RXF0 + (s << 3))) begin
										rd_data <= rx_data_bus[32 * s+:32];
										if (!rx_empty[s])
											rx_pop[s] <= 1'b1;
									end
									if (a32(rd_addr) == (kraken_pkg_AXIL_ADDR_TXF0 + (s << 3)))
										rd_data <= tx_hold[s];
								end
						end
					end
				endcase
				rd_done <= 1'b1;
			end
		end
	initial _sv2v_0 = 0;
endmodule
module kraken_sync2 (
	clk,
	rst_n,
	d,
	q
);
	parameter [31:0] W = 1;
	input wire clk;
	input wire rst_n;
	input wire [W - 1:0] d;
	output reg [W - 1:0] q;
	reg [W - 1:0] meta;
	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			meta <= 1'sb0;
			q <= 1'sb0;
		end
		else begin
			meta <= d;
			q <= meta;
		end
endmodule
module kraken_serial_host (
	clk,
	rst_n,
	sck_pad,
	sdio_pad,
	sdio_out,
	sdio_oe,
	req_stb,
	req_write,
	req_addr,
	req_wdata,
	rsp_data
);
	parameter [31:0] IDLE_CYCLES = 64;
	input wire clk;
	input wire rst_n;
	input wire sck_pad;
	input wire sdio_pad;
	output reg sdio_out;
	output reg sdio_oe;
	output reg req_stb;
	output reg req_write;
	output reg [11:0] req_addr;
	output reg [31:0] req_wdata;
	input wire [31:0] rsp_data;
	localparam [5:0] HDR_BITS = 6'd16;
	localparam [5:0] DATA_LSB = 6'd24;
	localparam [5:0] FRAME_BITS = 6'd56;
	reg [1:0] sck_sync;
	reg [1:0] sdio_sync;
	reg sck_q;
	reg [5:0] bit_cnt;
	reg [15:0] hdr;
	reg [31:0] wshift;
	reg [31:0] oshift;
	reg dir_r;
	reg [15:0] idle_cnt;
	wire sck = sck_sync[1];
	wire sdio = sdio_sync[1];
	wire sck_rise = sck & ~sck_q;
	wire sck_fall = ~sck & sck_q;
	wire in_data = bit_cnt >= DATA_LSB;
	wire drive = !dir_r && in_data;
	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			sck_sync <= 1'sb0;
			sdio_sync <= 1'sb0;
			sck_q <= 1'b0;
			bit_cnt <= 1'sb0;
			hdr <= 1'sb0;
			wshift <= 1'sb0;
			oshift <= 1'sb0;
			dir_r <= 1'b0;
			idle_cnt <= 1'sb0;
			sdio_out <= 1'b0;
			sdio_oe <= 1'b0;
			req_stb <= 1'b0;
			req_write <= 1'b0;
			req_addr <= 1'sb0;
			req_wdata <= 1'sb0;
		end
		else begin
			sck_sync <= {sck_sync[0], sck_pad};
			sdio_sync <= {sdio_sync[0], sdio_pad};
			sck_q <= sck;
			req_stb <= 1'b0;
			if (sck_rise || sck_fall)
				idle_cnt <= 1'sb0;
			else if (idle_cnt != IDLE_CYCLES[15:0])
				idle_cnt <= idle_cnt + 16'd1;
			if (idle_cnt == IDLE_CYCLES[15:0]) begin
				bit_cnt <= 1'sb0;
				sdio_oe <= 1'b0;
			end
			if (sck_rise) begin
				if (bit_cnt == 6'd0)
					dir_r <= sdio;
				if (bit_cnt < HDR_BITS)
					hdr <= {hdr[14:0], sdio};
				if (in_data)
					wshift <= {wshift[30:0], sdio};
				if ((bit_cnt == HDR_BITS) && !dir_r) begin
					req_stb <= 1'b1;
					req_write <= 1'b0;
					req_addr <= {hdr[11:2], 2'b00};
				end
				if ((bit_cnt == (FRAME_BITS - 6'd1)) && dir_r) begin
					req_stb <= 1'b1;
					req_write <= 1'b1;
					req_addr <= {hdr[11:2], 2'b00};
					req_wdata <= {wshift[30:0], sdio};
				end
				bit_cnt <= (bit_cnt == (FRAME_BITS - 6'd1) ? 6'd0 : bit_cnt + 6'd1);
			end
			if (sck_fall) begin
				sdio_oe <= drive;
				if (drive) begin
					if (bit_cnt == DATA_LSB) begin
						sdio_out <= rsp_data[31];
						oshift <= {rsp_data[30:0], 1'b0};
					end
					else begin
						sdio_out <= oshift[31];
						oshift <= {oshift[30:0], 1'b0};
					end
				end
			end
		end
endmodule
module kraken_tt_host (
	clk,
	rst_n,
	ena,
	ui_in,
	uo_out,
	uio_in,
	uio_out,
	uio_oe
);
	localparam [31:0] kraken_pkg_NUM_SM_DEFAULT = 1;
	parameter [31:0] NUM_SM = kraken_pkg_NUM_SM_DEFAULT;
	input wire clk;
	input wire rst_n;
	input wire ena;
	input wire [7:0] ui_in;
	output wire [7:0] uo_out;
	input wire [7:0] uio_in;
	output wire [7:0] uio_out;
	output wire [7:0] uio_oe;
	reg [2:0] state;
	reg aw_done;
	reg w_done;
	wire req_stb;
	wire req_write;
	wire [11:0] req_addr;
	wire [31:0] req_wdata;
	reg [31:0] rbuf;
	wire sdio_out;
	wire sdio_oe;
	reg [11:0] axil_awaddr;
	reg [11:0] axil_araddr;
	reg axil_awvalid;
	wire axil_awready;
	reg [31:0] axil_wdata;
	reg axil_wvalid;
	wire axil_wready;
	wire [1:0] axil_bresp;
	wire axil_bvalid;
	reg axil_arvalid;
	wire axil_arready;
	wire [31:0] axil_rdata;
	wire [1:0] axil_rresp;
	wire axil_rvalid;
	localparam [31:0] kraken_pkg_GPIO_W = 32;
	wire [31:0] gpio_in;
	wire [31:0] gpio_out;
	wire [31:0] gpio_oe;
	wire irq;
	wire [6:0] uio_in_s;
	wire [6:0] ui_in_s;
	kraken_serial_host u_link(
		.clk(clk),
		.rst_n(rst_n),
		.sck_pad(ui_in[7]),
		.sdio_pad(uio_in[7]),
		.sdio_out(sdio_out),
		.sdio_oe(sdio_oe),
		.req_stb(req_stb),
		.req_write(req_write),
		.req_addr(req_addr),
		.req_wdata(req_wdata),
		.rsp_data(rbuf)
	);
	kraken_sync2 #(.W(7)) u_sync_uio(
		.clk(clk),
		.rst_n(rst_n),
		.d(uio_in[6:0]),
		.q(uio_in_s)
	);
	kraken_sync2 #(.W(7)) u_sync_ui(
		.clk(clk),
		.rst_n(rst_n),
		.d(ui_in[6:0]),
		.q(ui_in_s)
	);
	assign gpio_in = {10'b0000000000, ui_in_s, gpio_out[14:7], uio_in_s};
	assign uio_out = {sdio_out, gpio_out[6:0]};
	assign uio_oe = {sdio_oe, gpio_oe[6:0]};
	assign uo_out = (ena ? gpio_out[14:7] : 8'b00000000);
	wire _unused = &{axil_bresp, axil_rresp, gpio_oe[31:7], gpio_out[31:15], irq, 1'b0};
	kraken_axil #(.NUM_SM(NUM_SM)) u_kraken(
		.clk(clk),
		.rst_n(rst_n),
		.s_axil_awaddr(axil_awaddr),
		.s_axil_awvalid(axil_awvalid),
		.s_axil_awready(axil_awready),
		.s_axil_wdata(axil_wdata),
		.s_axil_wstrb(4'b1111),
		.s_axil_wvalid(axil_wvalid),
		.s_axil_wready(axil_wready),
		.s_axil_bresp(axil_bresp),
		.s_axil_bvalid(axil_bvalid),
		.s_axil_bready(1'b1),
		.s_axil_araddr(axil_araddr),
		.s_axil_arvalid(axil_arvalid),
		.s_axil_arready(axil_arready),
		.s_axil_rdata(axil_rdata),
		.s_axil_rresp(axil_rresp),
		.s_axil_rvalid(axil_rvalid),
		.s_axil_rready(1'b1),
		.gpio_in(gpio_in),
		.gpio_out(gpio_out),
		.gpio_oe(gpio_oe),
		.irq(irq)
	);
	always @(posedge clk or negedge rst_n)
		if (!rst_n) begin
			state <= 3'd0;
			aw_done <= 1'b0;
			w_done <= 1'b0;
			rbuf <= 1'sb0;
			axil_awaddr <= 1'sb0;
			axil_awvalid <= 1'b0;
			axil_wdata <= 1'sb0;
			axil_wvalid <= 1'b0;
			axil_araddr <= 1'sb0;
			axil_arvalid <= 1'b0;
		end
		else
			(* full_case, parallel_case *)
			case (state)
				3'd0:
					if (req_stb) begin
						if (req_write) begin
							axil_awaddr <= req_addr;
							axil_wdata <= req_wdata;
							axil_awvalid <= 1'b1;
							axil_wvalid <= 1'b1;
							aw_done <= 1'b0;
							w_done <= 1'b0;
							state <= 3'd1;
						end
						else begin
							axil_araddr <= req_addr;
							axil_arvalid <= 1'b1;
							state <= 3'd3;
						end
					end
				3'd1: begin
					if (axil_awvalid && axil_awready) begin
						axil_awvalid <= 1'b0;
						aw_done <= 1'b1;
					end
					if (axil_wvalid && axil_wready) begin
						axil_wvalid <= 1'b0;
						w_done <= 1'b1;
					end
					if ((aw_done || (axil_awvalid && axil_awready)) && (w_done || (axil_wvalid && axil_wready))) begin
						state <= 3'd2;
						aw_done <= 1'b0;
						w_done <= 1'b0;
					end
				end
				3'd2:
					if (axil_bvalid)
						state <= 3'd0;
				3'd3:
					if (axil_arvalid && axil_arready) begin
						axil_arvalid <= 1'b0;
						state <= 3'd4;
					end
				3'd4:
					if (axil_rvalid) begin
						rbuf <= axil_rdata;
						state <= 3'd0;
					end
				default: state <= 3'd0;
			endcase
endmodule
`default_nettype none
module tt_um_kraken_x_protocol_emulator (
	ui_in,
	uo_out,
	uio_in,
	uio_out,
	uio_oe,
	ena,
	clk,
	rst_n
);
	input wire [7:0] ui_in;
	output wire [7:0] uo_out;
	input wire [7:0] uio_in;
	output wire [7:0] uio_out;
	output wire [7:0] uio_oe;
	input wire ena;
	input wire clk;
	input wire rst_n;
	kraken_tt_host u_kraken(
		.clk(clk),
		.rst_n(rst_n),
		.ena(ena),
		.ui_in(ui_in),
		.uo_out(uo_out),
		.uio_in(uio_in),
		.uio_out(uio_out),
		.uio_oe(uio_oe)
	);
endmodule